// A Spring Boot app deployed to App Service runs in a managed JVM.
// Azure auto-patches the OS and the (selected) Java runtime; you ship the jar.

// application.yml — bind to Azure-managed config
spring:
  datasource:
    url: ${AZURE_SQL_URL}        # injected by App Service from Key Vault
    username: ${AZURE_SQL_USER}
    password: ${AZURE_SQL_PASS}
  cloud:
    azure:
      key-vault:
        endpoint: ${KEY_VAULT_URI}   # secrets never in the jar

// The deploy contract: a single jar + a runtime stack (Java 17) +
//   an App Service plan (size + scaling rules). No servers to patch.
//   Application Insights (Azure's Micrometer-friendly APM) is wired
//   automatically when you add the spring-cloud-azure-starter.
